begin;
create schema admin_test;
create function admin_test.eq(actual bigint,expected bigint,label text) returns void language plpgsql as $$begin if actual is distinct from expected then raise exception 'FAIL % expected %, got %',label,expected,actual;end if;raise notice 'PASS %',label;end$$;
create function admin_test.denied(statement text,label text) returns void language plpgsql as $$begin begin execute statement;exception when insufficient_privilege then raise notice 'PASS %',label;return;end;raise exception 'FAIL % unauthorized operation succeeded',label;end$$;
grant usage on schema admin_test to anon,authenticated,castly_api;
grant execute on all functions in schema admin_test to anon,authenticated,castly_api;
insert into auth.users(id,raw_user_meta_data) values('70000000-0000-0000-0000-000000000001','{}'),('70000000-0000-0000-0000-000000000002','{}'),('70000000-0000-0000-0000-000000000003','{}');
set local castly.admin_bootstrap_reviewed='M7.1-owner-approved';
insert into admin_private.principals(user_id,roles,state) values('70000000-0000-0000-0000-000000000001',array['SUPER_ADMIN'],'active'),('70000000-0000-0000-0000-000000000002',array['ANALYST'],'active');
revoke usage on schema auth from castly_api;
select admin_test.eq((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='admin_private' and c.relkind='r' and c.relrowsecurity),7,'all seven administrative tables use RLS');
select admin_test.eq((select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('private','admin_private') and p.proname like 'admin_%' and p.prosecdef),0,'no admin SECURITY DEFINER functions');
set local role authenticated;
select admin_test.denied($$select * from admin_private.principals$$,'mobile cannot access admin principals');
select admin_test.denied($$select private.admin_permission('admins.manage')$$,'mobile cannot execute admin helper');
reset role;
select set_config('request.jwt.claim.sub','70000000-0000-0000-0000-000000000001',true);
set local role castly_api;
select admin_test.eq(has_schema_privilege(current_user,'auth','USAGE')::int,0,'no auth schema grant');
select admin_test.eq(private.admin_permission('admins.manage')::int,0,'super-admin role alone is not a session');
select admin_test.eq((select count(*) from admin_private.principals),1,'no session sees only own principal');
select set_config('request.admin.aal2','true',true),set_config('request.admin.mfa_at',now()::text,true),set_config('request.admin.auth_session','71000000-0000-0000-0000-000000000001',true),set_config('request.admin.reason','SQL security rehearsal',true);
insert into admin_private.sessions(user_id,auth_session_id,principal_version,ip_fingerprint,agent_family) values(private.request_user_id(),'71000000-0000-0000-0000-000000000001',1,'test-pseudonym','other') returning id as session_id \gset
select set_config('request.admin.session',:'session_id',true);
select admin_test.eq(private.admin_permission('admins.manage')::int,1,'valid TOTP-bound session receives explicit permission');
select admin_test.eq((select count(*) from admin_private.principals),2,'super admin directory works without RLS recursion');
select admin_test.denied($$update admin_private.principals set roles=array['SUPER_ADMIN'] where user_id='70000000-0000-0000-0000-000000000002'$$,'no application super-admin promotion');
with changed as(update admin_private.principals set roles=array['ANALYST'] where user_id=private.request_user_id() returning user_id)select admin_test.eq((select count(*) from changed),0,'self-change denied');
select admin_test.denied($$update admin_private.audit set reason='tamper'$$,'audit update not granted');
select admin_test.denied($$delete from admin_private.audit$$,'audit deletion not granted');
select admin_test.denied($$truncate admin_private.audit$$,'audit truncate not granted');
with changed as(update admin_private.authorizations set roles=array['SUPER_ADMIN'] returning user_id)select admin_test.eq((select count(*) from changed),0,'projection cannot be edited directly');
select admin_test.denied($$insert into admin_private.authorizations values('70000000-0000-0000-0000-000000000003',array['SUPER_ADMIN'],'active',1)$$,'projection cannot be inserted directly');
select admin_test.denied($$insert into admin_private.principals(user_id,roles,state) values('70000000-0000-0000-0000-000000000003',array['ANALYST'],'active')$$,'no uninvited activation');
select admin_test.denied($$insert into admin_private.sessions(user_id,auth_session_id,principal_version,ip_fingerprint,agent_family) values(private.request_user_id(),'71000000-0000-0000-0000-000000000002',1,'fixture','other')$$,'no auth session fixation');
select set_config('request.admin.aal2','false',true);
select admin_test.eq(private.admin_permission('admins.manage')::int,0,'MFA downgrade invalidates access');
select set_config('request.admin.aal2','true',true),set_config('request.admin.auth_session','71000000-0000-0000-0000-000000000002',true);
select admin_test.eq(private.admin_permission('admins.manage')::int,0,'different JWT session cannot reuse admin session');
select set_config('request.jwt.claim.sub','70000000-0000-0000-0000-000000000002',true);
select admin_test.eq((select count(*) from admin_private.authorizations),1,'projection selects only current actor');
select admin_test.eq((select count(*) from admin_private.audit),0,'analyst cannot read audit');
select admin_test.eq((select count(*) from admin_private.sessions),0,'analyst cannot enumerate other sessions');
select admin_test.denied($$insert into admin_private.invitations(user_id,roles,token_hash,created_by) values('70000000-0000-0000-0000-000000000003',array['ANALYST'],repeat('b',64),private.request_user_id())$$,'analyst cannot invite');
select admin_test.denied($$insert into admin_private.role_permissions values('ANALYST','admins.manage')$$,'permission definition writes denied');
reset role;
rollback;
